#!/usr/bin/env bash
set -euo pipefail

ANSIBLE_ENV_DIR="$HOME/.ansible/conf"
ANSIBLE_ENV_FILE="$ANSIBLE_ENV_DIR/env.yml"
VAULT_PASS_FILE="$ANSIBLE_ENV_DIR/.vaultpass.text"
if [ ! -s "$VAULT_PASS_FILE" ]; then
  VAULT_PASS_FILE="$ANSIBLE_ENV_DIR/.vaultpass.txt"
fi
if [ ! -s "$VAULT_PASS_FILE" ]; then
  echo "No vault password file found in $ANSIBLE_ENV_DIR" >&2
  exit 2
fi
if [ ! -f "$ANSIBLE_ENV_FILE" ]; then
  echo "No env.yml found at $ANSIBLE_ENV_FILE" >&2
  exit 3
fi

TIMESTAMP=$(date +%s)
TMP_PLAIN=$(mktemp /tmp/env_plain.XXXXXX)
TMP_CLEAN=$(mktemp /tmp/env_clean.XXXXXX)
BACKUP="${ANSIBLE_ENV_FILE}.bak.${TIMESTAMP}"
cp "$ANSIBLE_ENV_FILE" "$BACKUP" || true

ansible-vault view --vault-password-file "$VAULT_PASS_FILE" "$ANSIBLE_ENV_FILE" > "$TMP_PLAIN"

awk 'BEGIN{skip=0}
  /^OPENSHIFT_PULL_SECRET[[:space:]]*:/ { skip=1; next }
  { if (skip && $0 ~ /^[^[:space:]]/) { skip=0 } }
  { if (!skip) print }' "$TMP_PLAIN" > "$TMP_CLEAN"

cat >> "$TMP_CLEAN" <<'YAML'

OPENSHIFT_PULL_SECRET: |
  {"auths":{"cloud.openshift.com":{"auth":"b3BlbnNoaWZ0LXJlbGVhc2UtZGV2K29jbV9hY2Nlc3NfZGI1MGFkZmQ3Yjg2NDk4ZDg1NTY1NTQzMTI0ZjU4ZWY6MjFJU0FDSU1QUDlZTFlKSFhFMjQwN0hCOUk3UU1NNTBUT0ZVWVk2NFY5UzZRV1FWRTlXNEVHVDZHM1ZCQ1VTMQ==","email":"shadd@redhat.com"},"quay.io":{"auth":"b3BlbnNoaWZ0LXJlbGVhc2UtZGV2K29jbV9hY2Nlc3NfZGI1MGFkZmQ3Yjg2NDk4ZDg1NTY1NTQzMTI0ZjU4ZWY6MjFJU0FDSU1QUDlZTFlKSFhFMjQwN0hCOUk3UU1NNTBUT0ZVWVk2NFY5UzZRV1FWRTlXNEVHVDZHM1ZCQ1VTMQ==","email":"shadd@redhat.com"},"registry.connect.redhat.com":{"auth":"","email":"shadd@redhat.com"},"registry.redhat.io":{"auth":"","email":"shadd@redhat.com"}}}
YAML

ansible-vault encrypt --vault-password-file "$VAULT_PASS_FILE" "$TMP_CLEAN"
mv --force "$TMP_CLEAN" "$ANSIBLE_ENV_FILE"
chmod 600 "$ANSIBLE_ENV_FILE"
rm -f "$TMP_PLAIN"

echo "OK: updated $ANSIBLE_ENV_FILE (backup: $BACKUP)"
